diff --git a/test/ranges-test.cc b/test/ranges-test.cc
--- a/test/ranges-test.cc
+++ b/test/ranges-test.cc
@@ -16,6 +16,10 @@
 #include <vector>

+#if FMT_CPLUSPLUS > 201703L && FMT_HAS_INCLUDE(<ranges>)
+#  include <ranges>
+#endif
+
 #include "gtest/gtest.h"

 #if !FMT_GCC_VERSION || FMT_GCC_VERSION >= 601
@@ -421,6 +425,76 @@
 TEST(ranges_test, vector_char) {
   EXPECT_EQ(fmt::format("{}", std::vector<char>{'a', 'b'}), "['a', 'b']");
 }
+
+TEST(ranges_test, nested_char_range) {
+  auto v = std::vector<std::vector<char>>{{'a', '\n'}, {'b'}};
+  EXPECT_EQ(fmt::format("{}", v), "[['a', '\\n'], ['b']]");
+  EXPECT_EQ(fmt::format("{:n}", v), "['a', '\\n'], ['b']");
+  EXPECT_EQ(fmt::format("{::}", v), "[['a', '\\n'], ['b']]");
+  EXPECT_EQ(fmt::format("{:::}", v), "[[a, \n], [b]]");
+}
+
+#ifdef __cpp_lib_ranges
+TEST(ranges_test, split_view) {
+  auto line = std::string("a,b-c,d-e,f");
+  auto parts = line | std::views::split(',');
+  EXPECT_EQ(fmt::format("{}", parts),
+            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
+  EXPECT_EQ(fmt::format("{:n}", parts),
+            "['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']");
+  EXPECT_EQ(fmt::format("{:::}", parts),
+            "[[a], [b, -, c], [d, -, e], [f]]");
+
+  auto empty_parts = std::string(",a,,b,");
+  EXPECT_EQ(fmt::format("{}", empty_parts | std::views::split(',')),
+            "[[], ['a'], [], ['b'], []]");
+}
+
+struct non_const_char_range {
+  std::string_view sv;
+
+  template <std::ranges::range R>
+  non_const_char_range(R&& r)
+      : sv(std::ranges::data(r), std::ranges::distance(r)) {}
+
+  auto begin() { return sv.begin(); }
+  auto end() { return sv.end(); }
+};
+
+TEST(ranges_test, transformed_non_const_char_range) {
+  EXPECT_TRUE((fmt::is_range<non_const_char_range, char>::value));
+  EXPECT_TRUE((fmt::is_formattable<non_const_char_range>::value));
+  auto line = std::string("a,b-c,d-e,f");
+  auto parts = line | std::views::split(',') |
+               std::views::transform(
+                   [](auto part) { return non_const_char_range(part); });
+  EXPECT_EQ(fmt::format("{}", parts),
+            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
+}
+
+TEST(ranges_test, nested_split_view) {
+  auto line = std::string("a,b-c,d-e,f");
+  auto parts = line | std::views::split(',') |
+               std::views::transform(std::views::split('-'));
+  EXPECT_EQ(fmt::format("{}", parts),
+            "[[['a']], [['b'], ['c']], [['d'], ['e']], [['f']]]");
+  EXPECT_EQ(fmt::format("{:n}", parts),
+            "[['a']], [['b'], ['c']], [['d'], ['e']], [['f']]");
+}
+#endif  // __cpp_lib_ranges
